sys_script_include.script:
var GetStaleSWInstallations = Class.create();
GetStaleSWInstallations.prototype = {
    initialize: function() {},

    checkSoftwareModels: function() {
        var results = {}; // Object to store the final output

        var sm = new GlideRecord('cmdb_software_product_model');
        sm.addQuery('life_cycle_stage=Operational');
        sm.query();

        while (sm.next()) {
            var sysId = sm.getValue('sys_id');

            // Check for entitlement existence
            var ent = new GlideRecord('alm_license');
            ent.addEncodedQuery('model.sys_id=' + sysId);
            ent.setLimit(1);
            ent.query();
            var entitlementExists = ent.hasNext();

            // Check for suite existence
            var child = new GlideRecord('cmdb_m2m_suite_model');
            child.addEncodedQuery('suite_child.sys_id=' + sysId + '^ORsuite_parent.sys_id=' + sysId);
            child.setLimit(1);
            child.query();
            var suiteExists = child.hasNext();

            // Check for SaaS existence
            var saas = new GlideRecord('samp_sw_subscription');
            saas.addQuery('software_model.sys_id=' + sysId);
            saas.setLimit(1);
            saas.query();
            var saasExists = saas.hasNext();

            // Check for downgrade existence
            var dg = new GlideRecord('samp_sw_downgrade_model');
            dg.addEncodedQuery('model.sys_id=' + sysId + '^ORparent_model.sys_id=' + sysId);
            dg.setLimit(1);
            dg.query();
            var downgradeExists = dg.hasNext();

            // Store results for this sys_id
            results[sysId] = {
                entitlementExists: entitlementExists,
                suiteExists: suiteExists,
                saasExists: saasExists,
                downgradeExists: downgradeExists
            };
        }

        return results; // Return the structured results
    },

    type: 'GetStaleSWInstallations' // Name of the Script Include
};
